-- Datos para tabla: ordenes_compra

-- Datos para tabla: orden_compra_items

-- Datos para tabla: empleados

-- Ajustar secuencias de ID de PostgreSQL
SELECT setval(pg_get_serial_sequence('"unidades_medida"', 'id'), coalesce(max(id), 1)) FROM "unidades_medida";
SELECT setval(pg_get_serial_sequence('"categorias"', 'id'), coalesce(max(id), 1)) FROM "categorias";
SELECT setval(pg_get_serial_sequence('"productos"', 'id'), coalesce(max(id), 1)) FROM "productos";
SELECT setval(pg_get_serial_sequence('"clientes"', 'id'), coalesce(max(id), 1)) FROM "clientes";
SELECT setval(pg_get_serial_sequence('"proveedores"', 'id'), coalesce(max(id), 1)) FROM "proveedores";
SELECT setval(pg_get_serial_sequence('"facturas"', 'id'), coalesce(max(id), 1)) FROM "facturas";
SELECT setval(pg_get_serial_sequence('"factura_items"', 'id'), coalesce(max(id), 1)) FROM "factura_items";
SELECT setval(pg_get_serial_sequence('"recibos_caja"', 'id'), coalesce(max(id), 1)) FROM "recibos_caja";
SELECT setval(pg_get_serial_sequence('"cotizaciones"', 'id'), coalesce(max(id), 1)) FROM "cotizaciones";
SELECT setval(pg_get_serial_sequence('"cotizacion_items"', 'id'), coalesce(max(id), 1)) FROM "cotizacion_items";
SELECT setval(pg_get_serial_sequence('"remisiones"', 'id'), coalesce(max(id), 1)) FROM "remisiones";
SELECT setval(pg_get_serial_sequence('"remision_items"', 'id'), coalesce(max(id), 1)) FROM "remision_items";
SELECT setval(pg_get_serial_sequence('"ordenes_compra"', 'id'), coalesce(max(id), 1)) FROM "ordenes_compra";
